package com.example.frostbear.client;

import com.example.frostbear.entity.FrostBearMove;
import net.minecraft.client.model.EntityModel;
import net.minecraft.client.model.geom.ModelPart;
import net.minecraft.client.model.geom.builders.LayerDefinition;
import net.minecraft.util.Mth;

/**
 * The FrostBear: a hunched, crystal-crowned quadruped. Geometry and texture are
 * generated by tools/model/frostbear_model.py into {@link FrostBearModelLayer};
 * this class only animates the named parts.
 *
 * <p>Animation layers, in order: locomotion and idle breathing, the pose for the current
 * {@link FrostBearMove} (driven by the same synced tick as the server-side attack, so
 * every tell lines up with its hit), then the face. The body pivots at the hips, so
 * rearing lifts the shoulders while the hind legs are counter-rotated to stay planted.
 */
public class FrostBearEntityModel extends EntityModel<FrostBearRenderState> {
	/** The jaw hangs slightly open at rest, showing the fangs. */
	private static final float JAW_REST = 0.12F;
	private static final float BLINK_TICKS = 4.0F;

	private final ModelPart body;
	private final ModelPart neck;
	private final ModelPart head;
	private final ModelPart jaw;
	private final ModelPart nose;
	private final ModelPart leftBrow;
	private final ModelPart rightBrow;
	private final ModelPart leftEyelid;
	private final ModelPart rightEyelid;
	private final ModelPart leftEar;
	private final ModelPart rightEar;
	private final ModelPart tail;

	private final ModelPart frontLeftUpper;
	private final ModelPart frontRightUpper;
	private final ModelPart hindLeftUpper;
	private final ModelPart hindRightUpper;
	private final ModelPart frontLeftLower;
	private final ModelPart frontRightLower;
	private final ModelPart hindLeftLower;
	private final ModelPart hindRightLower;
	private final ModelPart frontLeftPaw;
	private final ModelPart frontRightPaw;
	private final ModelPart hindLeftPaw;
	private final ModelPart hindRightPaw;

	public FrostBearEntityModel(ModelPart root) {
		super(root);
		this.body = root.getChild("body");
		this.neck = this.body.getChild("neck");
		this.head = this.neck.getChild("head");
		this.jaw = this.head.getChild("jaw");
		this.nose = this.head.getChild("nose");
		this.leftBrow = this.head.getChild("left_brow");
		this.rightBrow = this.head.getChild("right_brow");
		this.leftEyelid = this.head.getChild("left_eyelid");
		this.rightEyelid = this.head.getChild("right_eyelid");
		this.leftEar = this.head.getChild("left_ear");
		this.rightEar = this.head.getChild("right_ear");
		this.tail = this.body.getChild("tail");

		this.frontLeftUpper = this.body.getChild("front_left_upper");
		this.frontRightUpper = this.body.getChild("front_right_upper");
		this.hindLeftUpper = this.body.getChild("hind_left_upper");
		this.hindRightUpper = this.body.getChild("hind_right_upper");
		this.frontLeftLower = this.frontLeftUpper.getChild("lower");
		this.frontRightLower = this.frontRightUpper.getChild("lower");
		this.hindLeftLower = this.hindLeftUpper.getChild("lower");
		this.hindRightLower = this.hindRightUpper.getChild("lower");
		this.frontLeftPaw = this.frontLeftLower.getChild("paw");
		this.frontRightPaw = this.frontRightLower.getChild("paw");
		this.hindLeftPaw = this.hindLeftLower.getChild("paw");
		this.hindRightPaw = this.hindRightLower.getChild("paw");
	}

	public static LayerDefinition getTexturedModelData() {
		return FrostBearModelLayer.create();
	}

	// ------------------------------------------------------------------------------------
	// Timing helpers: all in ticks since the move started
	// ------------------------------------------------------------------------------------

	/** 0 before {@code a}, 1 after {@code b}, smooth in between. */
	private static float ramp(float t, float a, float b) {
		float x = Mth.clamp((t - a) / (b - a), 0.0F, 1.0F);
		return x * x * (3.0F - 2.0F * x);
	}

	/** Rises over a–b, holds, falls over c–d. */
	private static float envelope(float t, float a, float b, float c, float d) {
		return Math.min(ramp(t, a, b), 1.0F - ramp(t, c, d));
	}

	@Override
	public void setupAnim(FrostBearRenderState state) {
		super.setupAnim(state);
		this.animateLocomotion(state);

		float t = state.moveTick;
		float wideEyes = 0.0F;
		float squint = 0.0F;
		float daze = 0.0F;
		switch (state.move) {
			case MAUL -> this.animateMaul(t);
			case ROAR -> wideEyes = this.animateRoar(t, FrostBearMove.ROAR.duration, 1.0F, state.ageInTicks);
			case TRANSITION -> wideEyes = this.animateRoar(t, FrostBearMove.TRANSITION.duration, 1.3F, state.ageInTicks);
			case BREATH -> squint = this.animateBreath(t);
			case SLAM -> this.animateSlam(t);
			case CHARGE_WINDUP -> this.animateChargeWindup(t);
			case CHARGE -> this.animateCharge(t);
			case STUNNED -> daze = this.animateStun(t, state.moveLength);
			case ICE_RING -> this.animateIceRing(t);
			case LEAP_CROUCH -> this.animateLeapCrouch(t);
			case LEAP -> this.animateLeap(t);
			case CATACLYSM -> wideEyes = this.animateCataclysm(t);
			case NONE -> {
			}
		}

		if (state.hurtTime > 0 && !state.isBusy()) {
			float recoil = state.hurtTime / 10.0F;
			this.body.zRot += Mth.sin(recoil * (float) Math.PI) * 0.1F;
			this.head.yRot += Mth.sin(recoil * (float) Math.PI) * 0.16F;
			this.leftEar.zRot -= 0.16F * recoil;
			this.rightEar.zRot += 0.16F * recoil;
		}

		this.animateFace(state, wideEyes, squint, daze);

		// The body pivots at the hips: keep the hind legs vertical while it rears or dips.
		this.hindLeftUpper.xRot -= this.body.xRot;
		this.hindRightUpper.xRot -= this.body.xRot;
	}

	// ------------------------------------------------------------------------------------
	// Locomotion and idle
	// ------------------------------------------------------------------------------------

	private void animateLocomotion(FrostBearRenderState state) {
		float age = state.ageInTicks;
		// in phase 2 it breathes harder
		float idleBreath = Mth.sin(age * (state.enraged ? 0.13F : 0.08F)) * (state.enraged ? 1.6F : 1.0F);
		float strideAmount = Math.min(state.walkAnimationSpeed * 1.35F, 1.0F);
		float stride = state.walkAnimationPos * 0.62F;
		float rightStep = Mth.cos(stride) * strideAmount;
		float leftStep = Mth.cos(stride + (float) Math.PI) * strideAmount;

		// heavy breathing and a rolling, shoulder-led gait
		this.body.y += idleBreath * 0.2F;
		this.body.y += Math.abs(Mth.sin(stride)) * 0.65F * strideAmount;
		this.body.zRot = Mth.cos(stride * 0.5F) * 0.045F * strideAmount;
		this.neck.xRot = -0.05F + idleBreath * 0.018F;
		this.head.yRot = state.yRot * Mth.DEG_TO_RAD + Mth.sin(age * 0.035F) * 0.055F;
		this.head.xRot = state.xRot * Mth.DEG_TO_RAD + 0.08F;
		this.jaw.xRot = JAW_REST + (idleBreath + 1.0F) * 0.02F;
		this.leftEar.zRot = -0.08F + Mth.sin(age * 0.11F) * 0.035F;
		this.rightEar.zRot = 0.08F - Mth.sin(age * 0.11F) * 0.035F;
		this.tail.yRot = Mth.sin(age * 0.07F) * 0.12F;

		this.frontRightUpper.xRot = rightStep * 0.85F;
		this.hindLeftUpper.xRot = rightStep * 0.72F;
		this.frontLeftUpper.xRot = leftStep * 0.85F;
		this.hindRightUpper.xRot = leftStep * 0.72F;
		this.frontRightLower.xRot = Math.max(0, -rightStep) * 0.5F;
		this.hindLeftLower.xRot = Math.max(0, -rightStep) * 0.45F;
		this.frontLeftLower.xRot = Math.max(0, -leftStep) * 0.5F;
		this.hindRightLower.xRot = Math.max(0, -leftStep) * 0.45F;
		this.frontRightPaw.xRot = -this.frontRightLower.xRot * 0.55F;
		this.frontLeftPaw.xRot = -this.frontLeftLower.xRot * 0.55F;
		this.hindRightPaw.xRot = -this.hindRightLower.xRot * 0.5F;
		this.hindLeftPaw.xRot = -this.hindLeftLower.xRot * 0.5F;
	}

	// ------------------------------------------------------------------------------------
	// Moves
	// ------------------------------------------------------------------------------------

	/** Raise the right paw (the tell), rake, raise the left, rake, then a lunging bite. */
	private void animateMaul(float t) {
		float rightRaise = envelope(t, 0, 12, FrostBearMove.MAUL_SWIPE_1, 18);
		float rightStrike = envelope(t, FrostBearMove.MAUL_SWIPE_1, 17, 19, 23);
		float leftRaise = envelope(t, 17, 21, FrostBearMove.MAUL_SWIPE_2, 26);
		float leftStrike = envelope(t, FrostBearMove.MAUL_SWIPE_2, 25, 27, 31);
		float bite = envelope(t, 26, 29, 32, 36);
		float jawOpen = envelope(t, 25, 29, 30, FrostBearMove.MAUL_BITE + 1);

		this.frontRightUpper.xRot += -1.4F * rightRaise + 0.45F * rightStrike;
		this.frontRightUpper.zRot += 0.3F * rightStrike;
		this.frontRightLower.xRot += 0.7F * rightRaise;
		this.frontLeftUpper.xRot += -1.3F * leftRaise + 0.45F * leftStrike;
		this.frontLeftUpper.zRot -= 0.3F * leftStrike;
		this.frontLeftLower.xRot += 0.7F * leftRaise;

		this.body.yRot += 0.2F * (rightRaise - leftRaise) - 0.12F * (rightStrike - leftStrike);
		this.body.xRot -= 0.12F * Math.max(rightRaise, leftRaise);
		this.neck.xRot += 0.35F * bite;
		this.head.xRot += 0.35F * bite;
		this.body.y += 0.8F * bite;
		this.jaw.xRot += 1.0F * jawOpen;
	}

	/** Rear up and bellow; returns how far into the pose it is (for wide eyes). */
	private float animateRoar(float t, int duration, float strength, float age) {
		float progress = t / duration;
		float pose = progress < 0.3F
				? ramp(progress, 0.0F, 0.3F)
				: progress < 0.82F ? 1.0F : 1.0F - ramp(progress, 0.82F, 1.0F);
		pose *= strength;
		this.body.xRot = -0.44F * pose;
		this.neck.xRot = -0.34F * pose;
		this.head.xRot = -0.62F * pose;
		this.jaw.xRot = JAW_REST + 1.0F * pose;
		this.frontLeftUpper.xRot -= 0.82F * pose;
		this.frontRightUpper.xRot -= 0.82F * pose;
		this.frontLeftLower.xRot += 0.28F * pose;
		this.frontRightLower.xRot += 0.28F * pose;
		this.leftEar.zRot -= 0.18F * pose;
		this.rightEar.zRot += 0.18F * pose;
		this.tail.xRot += 0.22F * pose;
		// shake the head at the peak
		this.head.zRot += Mth.sin(age * 1.4F) * 0.12F * pose * pose;
		return Math.min(pose, 1.0F);
	}

	/** Inhale (chest swells, head lifts), then exhale low with the jaw wide; returns the exhale. */
	private float animateBreath(float t) {
		float inhale = envelope(t, 0, 10, 14, FrostBearMove.BREATH_EXHALE + 1);
		float exhale = envelope(t, FrostBearMove.BREATH_EXHALE - 1, 19, FrostBearMove.BREATH_END - 2, FrostBearMove.BREATH.duration);
		this.body.y -= 0.6F * inhale;
		this.body.xRot -= 0.06F * inhale;
		this.neck.xRot -= 0.15F * inhale;
		this.head.xRot -= 0.3F * inhale;

		this.body.xRot += 0.08F * exhale;
		this.neck.xRot += 0.2F * exhale;
		this.head.xRot += 0.35F * exhale;
		this.jaw.xRot += 0.8F * exhale;
		this.frontLeftUpper.xRot += 0.12F * exhale;
		this.frontRightUpper.xRot += 0.12F * exhale;
		this.leftEar.zRot += 0.18F * exhale;
		this.rightEar.zRot -= 0.18F * exhale;
		return exhale;
	}

	/** Rear high (the tell), slam both forepaws down at the impact tick. */
	private void animateSlam(float t) {
		float rear = envelope(t, 0, 14, FrostBearMove.SLAM_IMPACT - 1, FrostBearMove.SLAM_IMPACT + 2);
		float impact = envelope(t, FrostBearMove.SLAM_IMPACT - 1, FrostBearMove.SLAM_IMPACT + 1, 20, 26);
		this.body.xRot += -0.55F * rear + 0.12F * impact;
		this.body.y += 1.0F * impact;
		this.neck.xRot += -0.12F * rear + 0.2F * impact;
		this.head.xRot += 0.14F * rear + 0.25F * impact;
		this.jaw.xRot += 0.5F * rear;
		this.frontLeftUpper.xRot += -1.25F * rear + 0.45F * impact;
		this.frontRightUpper.xRot += -1.25F * rear + 0.45F * impact;
		this.frontLeftLower.xRot += 0.35F * rear;
		this.frontRightLower.xRot += 0.35F * rear;
	}

	/** Crouch with the head low while a forepaw scrapes the ground. */
	private void animateChargeWindup(float t) {
		float crouch = ramp(t, 0, 6);
		float scrape = Mth.sin(t * 0.9F) * crouch;
		this.body.y += 1.6F * crouch;
		this.body.xRot += 0.1F * crouch;
		this.neck.xRot += 0.35F * crouch;
		this.head.xRot += 0.3F * crouch;
		this.jaw.xRot += 0.15F * crouch;
		this.frontLeftUpper.xRot += 0.55F * scrape;
		this.frontLeftLower.xRot += Math.max(0.0F, scrape) * 0.4F;
		this.tail.xRot += 0.4F * crouch;
	}

	/** A bounding gallop with the head down. */
	private void animateCharge(float t) {
		float pose = ramp(t, 0, 3);
		float gallop = t * 0.9F;
		this.frontLeftUpper.xRot = Mth.cos(gallop) * 0.9F * pose;
		this.frontRightUpper.xRot = Mth.cos(gallop + 0.4F) * 0.9F * pose;
		this.hindLeftUpper.xRot = Mth.cos(gallop + (float) Math.PI) * 0.8F * pose;
		this.hindRightUpper.xRot = Mth.cos(gallop + (float) Math.PI + 0.4F) * 0.8F * pose;
		this.body.xRot += (0.11F + Mth.sin(gallop) * 0.06F) * pose;
		this.body.y += Math.abs(Mth.sin(gallop)) * 0.6F * pose;
		this.neck.xRot += 0.28F * pose;
		this.head.xRot += 0.42F * pose;
		this.jaw.xRot += 0.22F * pose;
		this.tail.xRot += 0.3F * pose;
	}

	/** Head stuck low, swaying, ears flopped; returns how dazed it looks. */
	private float animateStun(float t, int length) {
		float daze = ramp(t, 0, 5) * (1.0F - ramp(t, length - 10, length));
		this.body.y += 1.2F * daze;
		this.body.zRot += Mth.sin(t * 0.18F) * 0.05F * daze;
		this.neck.xRot += 0.5F * daze;
		this.head.xRot += 0.45F * daze;
		this.head.zRot += Mth.sin(t * 0.25F) * 0.25F * daze;
		this.jaw.xRot += 0.45F * daze;
		this.leftEar.zRot -= 0.5F * daze;
		this.rightEar.zRot += 0.5F * daze;
		this.frontLeftUpper.zRot -= 0.12F * daze;
		this.frontRightUpper.zRot += 0.12F * daze;
		this.tail.xRot -= 0.3F * daze;
		return daze;
	}

	/** Hunch low (the tell), then spring up with the jaw open as the rings burst. */
	private void animateIceRing(float t) {
		float hunch = envelope(t, 0, 10, FrostBearMove.RING_BURST - 1, FrostBearMove.RING_BURST + 1);
		float burst = envelope(t, FrostBearMove.RING_BURST - 1, FrostBearMove.RING_BURST + 1, 22, 30);
		this.body.y += 2.2F * hunch - 1.5F * burst;
		this.body.xRot -= 0.25F * burst;
		this.frontLeftUpper.xRot += 0.3F * hunch - 0.4F * burst;
		this.frontRightUpper.xRot += 0.3F * hunch - 0.4F * burst;
		this.hindLeftUpper.xRot -= 0.3F * hunch;
		this.hindRightUpper.xRot -= 0.3F * hunch;
		this.neck.xRot += 0.3F * hunch;
		this.head.xRot += 0.2F * hunch - 0.45F * burst;
		this.jaw.xRot += 0.9F * burst;
	}

	/** Sink onto the hind legs, look up, and tremble before the jump. */
	private void animateLeapCrouch(float t) {
		float crouch = ramp(t, 0, 12);
		this.body.y += 3.0F * crouch;
		this.body.xRot -= 0.12F * crouch;
		this.body.zRot += Mth.sin(t * 3.0F) * 0.03F * ramp(t, 12, 20);
		this.hindLeftLower.xRot -= 0.6F * crouch;
		this.hindRightLower.xRot -= 0.6F * crouch;
		this.hindLeftUpper.xRot += 0.5F * crouch;
		this.hindRightUpper.xRot += 0.5F * crouch;
		this.frontLeftUpper.xRot -= 0.25F * crouch;
		this.frontRightUpper.xRot -= 0.25F * crouch;
		this.head.xRot -= 0.25F * crouch;
		this.jaw.xRot += 0.3F * crouch;
		this.tail.xRot += 0.3F * crouch;
	}

	/** Stretched out in the air, then a heavy landing crouch. */
	private void animateLeap(float t) {
		float stretch = envelope(t, 0, 4, 18, 23);
		float land = envelope(t, 21, 23, 27, 34);
		this.frontLeftUpper.xRot -= 1.0F * stretch - 0.35F * land;
		this.frontRightUpper.xRot -= 1.0F * stretch - 0.35F * land;
		this.frontLeftLower.xRot -= 0.2F * stretch;
		this.frontRightLower.xRot -= 0.2F * stretch;
		this.hindLeftUpper.xRot += 0.9F * stretch;
		this.hindRightUpper.xRot += 0.9F * stretch;
		this.hindLeftLower.xRot += 0.3F * stretch;
		this.hindRightLower.xRot += 0.3F * stretch;
		this.body.xRot -= 0.15F * stretch;
		this.body.y += 2.0F * land;
		this.neck.xRot += 0.3F * land;
		this.head.xRot += -0.2F * stretch + 0.3F * land;
		this.jaw.xRot += 0.7F * stretch + 0.4F * land;
		this.tail.xRot += 0.4F * stretch;
	}

	/** Half-rear and tremble while channelling, then crash forward on release. */
	private float animateCataclysm(float t) {
		float channel = ramp(t, 0, 12) * (1.0F - ramp(t, FrostBearMove.CATACLYSM_RELEASE, FrostBearMove.CATACLYSM_RELEASE + 4));
		float charge = ramp(t, 0, FrostBearMove.CATACLYSM_RELEASE);
		float release = envelope(t, FrostBearMove.CATACLYSM_RELEASE - 1, FrostBearMove.CATACLYSM_RELEASE + 1, 64, FrostBearMove.CATACLYSM.duration);
		this.body.xRot += -0.3F * channel + 0.2F * release;
		this.body.y += -0.6F * channel + 1.2F * release;
		this.body.zRot += Mth.sin(t * 2.2F) * 0.05F * channel * charge;
		this.frontLeftUpper.xRot += -0.6F * channel + 0.4F * release;
		this.frontRightUpper.xRot += -0.6F * channel + 0.4F * release;
		this.neck.xRot += -0.2F * channel + 0.3F * release;
		this.head.xRot += -0.5F * channel + 0.2F * release;
		this.jaw.xRot += 0.75F * channel * (0.6F + 0.4F * charge) + 1.1F * release;
		this.leftEar.xRot -= 0.5F * channel;
		this.rightEar.xRot -= 0.5F * channel;
		return channel;
	}

	// ------------------------------------------------------------------------------------
	// Face
	// ------------------------------------------------------------------------------------

	/**
	 * Facial expression layered over everything else: blinking, a hostile scowl, idle
	 * sniffs and yawns, wide eyes for the roars, a squint into the frost, a dazed stun,
	 * pain, and death.
	 */
	private void animateFace(FrostBearRenderState state, float wideEyes, float squint, float daze) {
		float t = state.ageInTicks + state.animationOffset;
		boolean hostile = state.aggressive || state.isBusy() || state.enraged;
		boolean dead = state.deathTime > 0.0F;
		float hurt = state.hurtTime / 10.0F;

		// eyelids: 0 = open, 1 = shut
		float blinkPeriod = 90.0F + state.animationOffset % 70.0F;
		float blinkPhase = t % blinkPeriod;
		float lid = blinkPhase < BLINK_TICKS ? Mth.sin(blinkPhase / BLINK_TICKS * (float) Math.PI) : 0.0F;
		if (hostile) {
			lid = Math.max(lid, 0.4F); // narrowed, glaring eyes
		}
		lid = Math.max(lid, 0.6F * squint);
		lid *= 1.0F - wideEyes;
		lid = Math.max(lid, 0.75F * daze);
		lid = Math.max(lid, hurt);

		// brows: a positive furrow drops the inner ends into a scowl, a negative one lifts them
		float furrow = Mth.lerp(wideEyes, hostile ? 0.2F : 0.04F, 0.3F) - 0.25F * hurt - 0.3F * daze;
		this.leftBrow.zRot = -furrow;
		this.rightBrow.zRot = furrow;
		this.leftBrow.y -= wideEyes;
		this.rightBrow.y -= wideEyes;

		if (hostile && daze < 0.5F) {
			// ears pinned back, a snarl that breathes, the snout wrinkled up
			this.leftEar.xRot -= 0.55F;
			this.rightEar.xRot -= 0.55F;
			if (!state.isBusy()) {
				this.jaw.xRot += 0.06F + Mth.sin(state.ageInTicks * 0.35F) * 0.04F;
			}
			this.nose.y -= 0.3F;
		} else if (!hostile && !dead) {
			// an occasional sniff: lift the head and twitch the nose
			float sniffPhase = t % 240.0F;
			if (sniffPhase < 30.0F) {
				float envelope = Mth.sin(sniffPhase / 30.0F * (float) Math.PI);
				this.head.xRot -= 0.12F * envelope;
				this.nose.y += Mth.sin(sniffPhase * 1.6F) * 0.35F * envelope;
			}
			// and a rare, slow yawn
			float yawnPhase = (t + 500.0F) % 900.0F;
			if (yawnPhase < 50.0F) {
				float envelope = Mth.sin(yawnPhase / 50.0F * (float) Math.PI);
				this.jaw.xRot += 0.9F * envelope;
				this.head.xRot -= 0.25F * envelope;
				lid = Math.max(lid, 0.9F * envelope);
			}
		}

		if (dead) {
			lid = 1.0F;
			this.jaw.xRot = JAW_REST + 0.5F;
		}
		setLid(this.leftEyelid, lid);
		setLid(this.rightEyelid, lid);
	}

	/** Lids hinge at their top edge; scaling them down opens the eye. */
	private static void setLid(ModelPart eyelid, float closed) {
		eyelid.visible = closed > 0.02F;
		eyelid.yScale = Math.max(closed, 0.02F);
	}
}
